import{_ as i}from"./chunks/image12.BRgDBKom.js";import{_ as n,o,c as a,am as r}from"./chunks/framework.CenUaW7a.js";const s="/projects/AiMechaM1/en/advanced-kit/assets/image1.6TmRqwWp.webp",t="/projects/AiMechaM1/en/advanced-kit/assets/image2.BX4e1shk.png",c="/projects/AiMechaM1/en/advanced-kit/assets/image3.B3n0jRl9.png",l="/projects/AiMechaM1/en/advanced-kit/assets/image4.xi51yKxl.png",d="/projects/AiMechaM1/en/advanced-kit/assets/image5.DrLG1TdH.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image6.Cx33jQiU.png",_=JSON.parse('{"title":"3.25 Lesson 25: Traffic Sign Detection","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.25 Lesson 25 Traffic Sign Detection.md","filePath":"docs/3. Course materials/3.25 Lesson 25 Traffic Sign Detection.md"}'),g={name:"docs/3. Course materials/3.25 Lesson 25 Traffic Sign Detection.md"};function h(u,e,m,f,v,y){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-25-lesson-25-traffic-sign-detection" tabindex="-1">3.25 Lesson 25: Traffic Sign Detection <a class="header-anchor" href="#_3-25-lesson-25-traffic-sign-detection" aria-label="Permalink to &quot;3.25 Lesson 25: Traffic Sign Detection&quot;">​</a></h1><h2 id="_3-25-1-lesson-introduction" tabindex="-1">3.25.1 Lesson Introduction <a class="header-anchor" href="#_3-25-1-lesson-introduction" aria-label="Permalink to &quot;3.25.1 Lesson Introduction&quot;">​</a></h2><p>Focusing on K230 traffic sign detection, this lesson explores autonomous driving applications. Taking inspiration from self-driving cars recognizing road signs and unmanned delivery vehicles reading street markers, this section covers dedicated model recognition for signs such as go straight, turn left, turn right, and stop. Centered around &quot;sign-guided automated driving&quot;, this lesson designs an intelligent driving simulation where recognizing signs triggers forward movement, left turns, or right turns for 2 s. Combining visual detection with traffic scenarios establishes a clear understanding of the &quot;perception → decision → execution&quot; autonomous driving pipeline. Incorporating line following alongside traffic sign detection introduces advanced gameplay, expanding real-world driving scenarios and inspiring further exploration into intelligent transportation.</p><h2 id="_3-25-2-learning-objectives" tabindex="-1">3.25.2 Learning Objectives <a class="header-anchor" href="#_3-25-2-learning-objectives" aria-label="Permalink to &quot;3.25.2 Learning Objectives&quot;">​</a></h2><ol><li><p>Understand the technical principles and application scenarios of traffic sign detection. Master the characteristics and advantages of dedicated object detection models, learn the core functions of the autonomous driving perception layer, and comprehend the decision-guiding role of traffic signs in intelligent driving.</p></li><li><p>Enable the traffic sign detection mode on the K230 module and verify its functionality. Master the programming commands for traffic sign detection, and retrieve the name and parameters of the traffic sign closest to the center of the frame.</p></li><li><p>Establish a systems mindset for autonomous driving based on the perception-decision-execution framework. Cultivate rule-driven behavioral decision-making capabilities, and enhance design skills in scenario-based programming and task abstraction.</p></li><li><p>Relate these concepts to real-world application scenarios, such as autonomous driving, advanced driver assistance systems, also known as ADAS, unmanned delivery vehicles, smart traffic management, and campus logistics vehicles, to understand the core value of traffic sign detection in intelligent mobility.</p></li></ol><h2 id="_3-25-3-preparation" tabindex="-1">3.25.3 Preparation <a class="header-anchor" href="#_3-25-3-preparation" aria-label="Permalink to &quot;3.25.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li><p>AiMecha M1 Mecanum-Wheel Car Advanced Kit</p></li><li><p>Type-C data cable</p></li><li><p>Computer × 1</p></li><li><p>Remote controller</p></li></ul><p><strong>Software Preparation</strong>:</p><ul><li>WonderLab graphical programming software</li></ul><p><strong>Core Concept Description</strong>:</p><ul><li><p><strong>Traffic Sign Detection</strong>: Specialized object detection optimized for traffic scenarios that recognizes various traffic signs and outputs their categories and locations.</p></li><li><p><strong>Recognizable Signs</strong>: Go straight, turn left, turn right, stop, U-turn, traffic lights, crosswalk, and speed limit sign cards.</p></li><li><p><strong>Autonomous Driving Perception Layer</strong>: Acts as the &quot;eyes&quot; of the autonomous driving system to identify all road traffic elements.</p></li></ul><p><strong>Wiring Instructions</strong>:</p><ul><li>Connect the K230 screen module to <strong>port A</strong> of the controller.</li></ul><p><strong>Menu Navigation Path</strong>:</p><ul><li>Recognition Mode → AI Application → Traffic Detection.</li></ul><p><strong>Factors Influencing Recognition Performance</strong>:</p><ul><li><p>Face sign cards directly toward the camera for optimal results, as excessive tilt angles reduce the recognition rate.</p></li><li><p>Ensure uniform and sufficient lighting, as glare or shadows may reduce accuracy.</p></li><li><p>Keep the sign at a moderate size within the frame, ensuring it remains clear, intact, and unobstructed.</p></li><li><p>Use a clean background with minimal clutter for better recognition performance.</p></li></ul><p><strong>Three-Layer Autonomous Driving Architecture</strong>:</p><ul><li><p><strong>Perception Layer</strong>: Uses sensors such as cameras and LiDARs to perceive the environment, with traffic sign detection in this lesson belonging to the perception layer.</p></li><li><p><strong>Decision Layer</strong>: Evaluates perceptual information to determine appropriate actions such as going straight, turning, or stopping.</p></li><li><p><strong>Execution Layer</strong>: Controls actuators such as motors and servos to complete physical movements.</p></li></ul><h2 id="_3-25-4-hands-on-project" tabindex="-1">3.25.4 Hands-On Project <a class="header-anchor" href="#_3-25-4-hands-on-project" aria-label="Permalink to &quot;3.25.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This project builds a vision-guided intelligent driving simulation system, reproducing the three-layer autonomous driving architecture of perception, decision-making, and execution. The perception layer relies on the K230 camera to capture frames, recognizing traffic signs via models to output categories, confidence scores, and positional information. The decision-making layer adopts sign-driven rule logic, triggering forward movement, left turns, or right turns upon recognizing corresponding signs. The execution layer drives the Mecanum-wheel car to complete actions, automatically stopping and waiting for new commands after each execution. Building this system provides an intuitive understanding of autonomous driving principles and establishes system-level architecture cognition.</p><img loading="lazy" height="540" width="960" src="'+s+'" class="common_img" style="width:400px;aspect-ratio:960 / 540;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="741" width="551" src="'+t+'" class="common_img" style="width:300px;aspect-ratio:551 / 741;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Presence detection</td><td style="text-align:center;"><img loading="lazy" height="56" width="294" src="'+c+'" class="common_img" style="width:100px;aspect-ratio:294 / 56;"></td><td style="text-align:left;">Determines whether any traffic sign is present in the frame and returns a boolean value.</td></tr><tr><td style="text-align:center;">Quantity counting</td><td style="text-align:center;"><img loading="lazy" height="51" width="357" src="'+l+'" class="common_img" style="width:100px;aspect-ratio:357 / 51;"></td><td style="text-align:left;">Counts the number of traffic signs detected in the frame.</td></tr><tr><td style="text-align:center;">Detailed parameters</td><td style="text-align:center;"><img loading="lazy" height="255" width="589" src="'+d+'" class="common_img" style="width:100px;aspect-ratio:589 / 255;"></td><td style="text-align:left;">Reads parameters such as the name, confidence, coordinates, and dimensions of the central sign.</td></tr><tr><td style="text-align:center;">Name matching</td><td style="text-align:center;"><img loading="lazy" height="220" width="632" src="'+p+'" class="common_img" style="width:100px;aspect-ratio:632 / 220;"></td><td style="text-align:left;">Directly evaluates whether a sign matches a specified category to simplify conditional logic.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task: Recognizing Different Traffic Signs to Execute Corresponding Driving Actions</strong></p><ul><li><p>Initialization settings: At startup, initialize port A, set the running mode to traffic detection, and start detection.</p></li><li><p>Main loop structure: Execute <code>Update and save result data</code> as the first step inside the repeat forever loop to synchronize the latest traffic sign detection data.</p></li><li><p>Go straight branch: If <code>Traffic detection results near the center are named move forward</code>, drive the Mecanum-wheel car forward at the specified power, wait 2 s, and stop the car so that it moves forward for 2 s and stops upon detecting a straight sign.</p></li><li><p>Turn left branch: If <code>Traffic detection results near the center are named Turn left</code>, spin the Mecanum-wheel car left in place at the specified power, wait 2 s, and stop the car so that it turns left for 2 s and stops upon detecting a left-turn sign.</p></li><li><p>Turn right branch: If <code>Traffic detection results near the center are named turn Right</code>, spin the Mecanum-wheel car right in place at the specified power, wait 2 s, and stop the car so that it turns right for 2 s and stops upon detecting a right-turn sign.</p></li><li><p>Stop sign branch: Expand the program with a stop sign branch to bring the car to an immediate halt upon detection.</p></li><li><p>Sign trigger mechanism: Trigger one complete action sequence per sign and ignore new signs during execution to ensure each action completes fully.</p></li></ul><img loading="lazy" height="741" width="551" src="'+t+'" class="common_img" style="width:300px;aspect-ratio:551 / 741;"><p><strong>Program Design Key Points</strong></p><ul><li><p>Direct name evaluation: Use the <code>Traffic detection results are named XX</code> command to evaluate sign categories directly and simplify programming.</p></li><li><p>Action duration: Adjust the 2 s action duration according to actual performance to achieve appropriate turning angles or forward distances.</p></li><li><p>Center priority: Default to the sign closest to the center to prevent confusion when multiple signs appear near the edges of the frame.</p></li><li><p>Stop and reset: Stop the car after each action completes to ensure a single sign triggers a single action.</p></li><li><p>High scalability: Add a new if branch to incorporate additional sign types within the unified framework.</p></li></ul><p><strong>Advanced Challenge: Line Following + Autonomous Driving with Traffic Sign Recognition</strong></p><ul><li><p>Combine the 6-channel line follower sensor to guide the car along black tape tracks.</p></li><li><p>Execute corresponding actions upon encountering traffic sign cards along the route: stop for 3 s at a stop sign before proceeding, and spin in place to return at a U-turn sign.</p></li><li><p>Simulate real road scenarios to build a comprehensive autonomous driving experience.</p></li><li><p>Multi-sensor fusion: Use line following for lane keeping and visual sign recognition for traffic rule decision-making so both systems work in coordination.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1qESIR7n_mxv3oQTrZhNbBTnPKVOk-yT4?usp=sharing" target="_blank" rel="noreferrer">Program Files/Traffic Sign Detection</a>.</strong></p></div></li></ul><p><strong>Program Upload:</strong></p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port located above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to download the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+i+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-25-5-expansion-and-advancement" tabindex="-1">3.25.5 Expansion and Advancement <a class="header-anchor" href="#_3-25-5-expansion-and-advancement" aria-label="Permalink to &quot;3.25.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Expansion Project 1: Complete Traffic Rules Autonomous Driving System</strong></p><p>Expand traffic sign categories to over eight types and design a comprehensive traffic rule system: stop at red lights, proceed at green lights, slow down at yellow lights, decelerate and yield at crosswalks, reduce speed at speed limit signs, stop for 3 s at stop signs, and perform a 180° turn at U-turn signs. Construct a simulated road with multiple traffic signs and program the car to autonomously recognize signs and follow traffic rules throughout the route, building a miniature autonomous driving demonstration system that reproduces smart vehicle driving logic.</p><p><strong>Expansion Project 2: Traffic Sign Voice Announcement Assistant</strong></p><p>Combine the buzzer or voice module to design a traffic sign announcement system: play a reminder tone upon recognizing a &quot;School Ahead&quot; sign, announce the speed limit value upon recognizing a &quot;Speed Limit&quot; sign, and sound an alarm upon recognizing a &quot;Danger&quot; sign. Simulate the voice prompt functions of advanced driver assistance systems to understand how ADAS provides timely road condition alerts and explore human-vehicle collaborative driving interaction modes.</p><h2 id="_3-25-6-q-a" tabindex="-1">3.25.6 Q&amp;A <a class="header-anchor" href="#_3-25-6-q-a" aria-label="Permalink to &quot;3.25.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: What makes traffic sign recognition indispensable in autonomous driving perception?</strong></p><p><strong>Answer</strong>: Traffic sign recognition represents one component of the autonomous driving perception layer, working alongside lane line detection, vehicle detection, traffic light recognition, and obstacle detection to build a complete understanding of the environment.</p><p><strong>Q2: What is the difference between traffic sign detection and general object detection?</strong></p><p><strong>Answer</strong>: Traffic sign detection uses a <strong>specialized detection model tailored for a vertical domain</strong>, delivering significantly higher accuracy in specific traffic scenarios compared to general object detection and illustrating the difference between &quot;specialized precision&quot; and &quot;general breadth&quot;.</p><h2 id="_3-25-7-technical-support-and-discussion" tabindex="-1">3.25.7 Technical Support and Discussion <a class="header-anchor" href="#_3-25-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.25.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',51)])])}const x=n(g,[["render",h]]);export{_ as __pageData,x as default};
